package set

import "testing"

func TestAddContains(t *testing.T) {
	s := New[int]()
	s.Add(1)
	s.Add(2)
	if !s.Contains(1) || !s.Contains(2) { t.Fatal("missing added elements") }
	if s.Contains(3) { t.Fatal("should not contain 3") }
}

func TestRemove(t *testing.T) {
	s := New[string]()
	s.Add("a")
	s.Add("b")
	s.Remove("a")
	if s.Contains("a") { t.Fatal("a should be removed") }
	if !s.Contains("b") { t.Fatal("b should remain") }
}

func TestLen(t *testing.T) {
	s := New[int]()
	if s.Len() != 0 { t.Fatal("new set should have len 0") }
	s.Add(1)
	s.Add(1) // duplicate
	s.Add(2)
	if s.Len() != 2 { t.Fatalf("want 2, got %d", s.Len()) }
}

func TestUnion(t *testing.T) {
	a := New[int]()
	a.Add(1); a.Add(2)
	b := New[int]()
	b.Add(2); b.Add(3)
	u := a.Union(b)
	if u.Len() != 3 { t.Fatalf("want 3, got %d", u.Len()) }
	if !u.Contains(1) || !u.Contains(2) || !u.Contains(3) { t.Fatal("union missing element") }
}

func TestIntersection(t *testing.T) {
	a := New[int]()
	a.Add(1); a.Add(2); a.Add(3)
	b := New[int]()
	b.Add(2); b.Add(3); b.Add(4)
	i := a.Intersection(b)
	if i.Len() != 2 { t.Fatalf("want 2, got %d", i.Len()) }
	if !i.Contains(2) || !i.Contains(3) { t.Fatal("intersection missing element") }
	if i.Contains(1) || i.Contains(4) { t.Fatal("intersection has wrong element") }
}
